public struct FfiConverterTypeCastingDevice: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = CastingDevice

    public static func lift(_ handle: UInt64) throws -> CastingDevice {
        return CastingDevice(unsafeFromHandle: handle)
    }

    public static func lower(_ value: CastingDevice) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CastingDevice {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: CastingDevice, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


